CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS portfolios (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, horizon INT NOT NULL, cash DECIMAL(18,2) NOT NULL DEFAULT 0, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id), CHECK(horizon IN(1,2,5)), CHECK(cash>=0));
CREATE TABLE IF NOT EXISTS holdings (portfolio_id CHAR(36) NOT NULL, symbol VARCHAR(10) NOT NULL, quantity INT NOT NULL, PRIMARY KEY(portfolio_id,symbol), FOREIGN KEY(portfolio_id) REFERENCES portfolios(id), CHECK(quantity>=0));
CREATE TABLE IF NOT EXISTS commands (portfolio_id CHAR(36) NOT NULL, request_key VARCHAR(100) NOT NULL, fingerprint CHAR(64) NOT NULL, result JSON NOT NULL, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(portfolio_id,request_key), FOREIGN KEY(portfolio_id) REFERENCES portfolios(id));
CREATE TABLE IF NOT EXISTS quotes (symbol VARCHAR(10) PRIMARY KEY, price DECIMAL(18,4) NOT NULL, observed_at DATETIME(3) NOT NULL, retrieved_at DATETIME(3) NOT NULL, provider VARCHAR(40) NOT NULL, currency CHAR(3) NOT NULL, adjustment_status VARCHAR(20) NOT NULL, CHECK(price>0));
CREATE TABLE IF NOT EXISTS prices (symbol VARCHAR(10) NOT NULL, observed_date DATE NOT NULL, adjusted_close DECIMAL(18,6) NOT NULL, provider VARCHAR(40) NOT NULL, retrieved_at DATETIME(3) NOT NULL, currency CHAR(3) NOT NULL, adjustment_status VARCHAR(30) NOT NULL, PRIMARY KEY(symbol,observed_date,provider), CHECK(adjusted_close>0));
CREATE TABLE IF NOT EXISTS orders (id CHAR(36) PRIMARY KEY, portfolio_id CHAR(36) NOT NULL, symbol VARCHAR(10) NOT NULL, side ENUM('BUY','SELL') NOT NULL, quantity INT NOT NULL, status ENUM('PENDING','FILLED','CANCELLED','REJECTED') NOT NULL, reason VARCHAR(200), created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(portfolio_id) REFERENCES portfolios(id), INDEX(status,created_at), CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS batches (id VARCHAR(100) PRIMARY KEY, cutoff DATETIME(3) NOT NULL, result JSON NOT NULL, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS executions (id CHAR(36) PRIMARY KEY, order_id CHAR(36) NOT NULL UNIQUE, batch_id VARCHAR(100), quantity INT NOT NULL, price DECIMAL(18,4) NOT NULL, amount DECIMAL(18,2) NOT NULL, observed_at DATETIME(3) NOT NULL, executed_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(batch_id) REFERENCES batches(id));
CREATE TABLE IF NOT EXISTS basket_allocations (batch_id VARCHAR(100) NOT NULL, order_id CHAR(36) NOT NULL UNIQUE, symbol VARCHAR(10) NOT NULL, side ENUM('BUY','SELL') NOT NULL, quantity INT NOT NULL, amount DECIMAL(18,2) NOT NULL, PRIMARY KEY(batch_id,order_id), FOREIGN KEY(batch_id) REFERENCES batches(id), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS recommendations (id CHAR(36) PRIMARY KEY, portfolio_id CHAR(36) NOT NULL, cutoff DATE NOT NULL, payload JSON NOT NULL, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(portfolio_id) REFERENCES portfolios(id), INDEX(portfolio_id,cutoff));
CREATE TABLE IF NOT EXISTS evaluations (id CHAR(36) PRIMARY KEY, recommendation_id CHAR(36) NOT NULL, end_date DATE NOT NULL, payload JSON NOT NULL, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(recommendation_id,end_date), FOREIGN KEY(recommendation_id) REFERENCES recommendations(id));
CREATE TABLE IF NOT EXISTS simulator_lock (id INT PRIMARY KEY);
